inputs = ['cwjhzw', 'axxaae', 'ghviaa', 'fhhbzd', 'whbzz']
outputs = ['yuawjhzw', 'axxaae', 'zhviaa', 'fhhbzd', 'whbzz']

rules = [
    "replace('g', 'z')",
    "replace('c', 'yu')"
]

# Apply rules in order
def apply_rule(string, rule_str):
    # Parse the rule string
    # Expected format: "replace('pattern', 'replacement')"
    import re
    match = re.match(r"replace\('(.*)', '(.*)'\)", rule_str)
    if match:
        pattern, replacement = match.groups()
        return string.replace(pattern, replacement)
    return string

